import chess

_V = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.0, chess.ROOK: 5.0,
      chess.QUEEN: 9.0, chess.KING: 20.0}
_RW = {chess.KNIGHT: 1.0, chess.BISHOP: 1.0, chess.ROOK: 1.2, chess.QUEEN: 1.5}

MOTIF_NAME = 'opponent pieces cornered and hanging'
MOTIF_DESCRIPTION = 'Without holding more than a one-pawn material lead, the side to move troubles the opponent pieces far more than its own are troubled: more enemy knights, bishops, rooks and queens have at most one safe square available, and more of them stand attacked while undefended, hit by a cheaper unit, or attacked more times than defended.'


def _mat(b, c):
    return (len(b.pieces(chess.PAWN, c)) + 3 * len(b.pieces(chess.KNIGHT, c))
            + 3 * len(b.pieces(chess.BISHOP, c)) + 5 * len(b.pieces(chess.ROOK, c))
            + 9 * len(b.pieces(chess.QUEEN, c)))


def _cheap(b, c, sq):
    best = 99.0
    for x in b.attackers(c, sq):
        p = b.piece_at(x)
        if p is not None and _V[p.piece_type] < best:
            best = _V[p.piece_type]
    return best


def _free(b, sq, d, a, v):
    n = 0
    for t in b.attacks(sq):
        occ = b.piece_at(t)
        if occ is not None and occ.color == d:
            continue
        gain = _V[occ.piece_type] if occ is not None else 0.0
        at = b.attackers(a, t)
        if not at or gain >= v - 0.4:
            n += 1
        else:
            c = _cheap(b, a, t)
            if c >= v - 0.4 and b.attackers(d, t):
                n += 1
        if n >= 2:
            return 2
    return n


def _trouble(b, a, d):
    s = 0.0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        v = _V[pt]
        w = _RW[pt]
        for sq in b.pieces(pt, d):
            f = _free(b, sq, d, a, v)
            if f < 2:
                s += w * (2 - f)
            at = b.attackers(a, sq)
            if at:
                df = b.attackers(d, sq)
                if not df or _cheap(b, a, sq) + 0.5 < v:
                    s += 1.2
                elif len(at) > len(df):
                    s += 0.5
    return s


def motif(fen: str) -> bool:
    b = chess.Board(fen)
    us = b.turn
    them = not us
    if b.king(us) is None or b.king(them) is None:
        return False
    if len(b.piece_map()) < 10:
        return False
    if _mat(b, us) - _mat(b, them) > 1:
        return False
    ours = _trouble(b, us, them)
    theirs = _trouble(b, them, us)
    return ours >= 2.0 and (ours - theirs) >= 1.5
